styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(14, 1fr);
  align-items: center;
  column-gap: var(--g-gap);
  min-height: calc(var(--vh, 1vh) * 100);
}

section[data-skill-hub] form {
  grid-row-start: 1;
  grid-row-end: 2;
  grid-column-start: 2;
  grid-column-end: 14;

  position: relative;
  background-color: #3687ff;
  color: var(--c-white);

  margin-top: calc(var(--h1) * 2);
  margin-bottom: calc(var(--h1) * 2);

  width: 100%;
  padding-top: var(--p);
  padding-bottom: var(--p);
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  column-gap: var(--g-gap);
}
section[data-skill-hub] fieldset {
  margin: 0;
  padding: var(--g-gap);
  border: none;
  position: relative;
  padding-bottom: var(--h6);
}
section[data-skill-hub] input,
section[data-skill-hub] textarea {
  padding: var(--g-gap);
  display: block;
  width: 100%;
  border: none;
  background-color: #1e67d1;
  color: var(--c-white);
  outline: none;
  border-radius: 0;
  box-shadow: none;
}
section[data-skill-hub] input::placeholder,
section[data-skill-hub] textarea::placeholder {
  color: #1853a8;
}
section[data-skill-hub] fieldset:has(input[type='checkbox']) {
  display: flex;
  align-items: baseline;
  align-self: center;
}
section[data-skill-hub] fieldset:has(input[type='checkbox']) input {
  display: inline-block;
  width: auto;
  margin-right: var(--g-gap);
}

section[data-skill-hub] input.-error,
section[data-skill-hub] textarea.-error {
}

section[data-skill-hub] input.-valid,
section[data-skill-hub] textarea.-valid {
  /* border-color: green; */
}

section[data-skill-hub] fieldset[string-input^='group'].-error label::after {
  content: '*';
  color: var(--c-red);
}
section[data-skill-hub] fieldset[string-input^='error'] span {
}
section[data-skill-hub] .-invalid div[string-input^='error'],
section[data-skill-hub] .-error div[string-input^='error'] {
  position: absolute;
  top: calc(100% - var(--h6));
  left: var(--g-gap);
  background-color: var(--c-white);
  border-radius: 0.2rem;
  padding: 0 var(--g-gap);
  box-shadow: 0 0.2rem 0.4rem #00000020;
}
section[data-skill-hub] .-invalid div[string-input^='error'] span,
section[data-skill-hub] .-error div[string-input^='error'] span {
  display: block;
  font-size: 0.6rem;
}
section[data-skill-hub] .-invalid div[string-input^='error'] span::before,
section[data-skill-hub] .-error div[string-input^='error'] span::before {
  content: '•';
  margin-right: var(--g-gap);
}
section[data-skill-hub] .-invalid div[string-input^='error'] span::after,
section[data-skill-hub] .-error div[string-input^='error'] span::after {
  content: ';';
}
section[data-skill-hub] .-invalid div[string-input^='error'] span:last-child::after,
section[data-skill-hub] .-error div[string-input^='error'] span:last-child::after {
  content: '.';
}
section[data-skill-hub] .-invalid div[string-input^='error'] span {
  color: #1853a8;
}
section[data-skill-hub] .-error div[string-input^='error'] span {
  color: #d98c75;
}

section[data-skill-hub] button {
  align-self: center;
  display: inline-block;
  padding: var(--g-gap);
  background-color: var(--c-white);
  color: var(--c-black);
  margin: var(--p) var(--g-gap) var(--h6) var(--g-gap);
}

@media (min-width: 1024px) {
  section[data-skill-hub] form {
    grid-column-start: 4;
    grid-column-end: 12;

    grid-template-columns: repeat(2, 1fr);
  }
}

section[data-skill-hub] .popup {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  overflow: auto;
  background-color: var(--c-white);
  color: var(--c-black);
  padding: var(--g-gap);

  visibility: hidden;
}
section[data-skill-hub] .popup code {
}
section[data-skill-hub] .popup.-opened {
  visibility: visible;
}

scripts.tutorial:
setTimeout(() => {
  const stringTune = window.StringTuneContext;
  const popup = document.getElementById('popup');
  const popupCode = document.getElementById('popup-code');

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      popup.classList.remove('-opened');
    }
  });

  document.documentElement.addEventListener('click', (e) => {
    popup.classList.remove('-opened');
  });

  stringTune.on('form:submit:validation-demo', (data) => {
    popupCode.innerText = JSON.stringify(data, null, 2);
    popup.classList.add('-opened');
  });
  stringTune.on('form:invalid:validation-demo', () => {});
}, 2000);
